// Helper kernel for copying alpha to beta
template <typename T, typename S, typename U>
ROCSOLVER_KERNEL void copy_alpha_to_beta(U alphaA,
                                          const rocblas_stride shifta,
                                          const rocblas_stride stridea,
                                          S* betaA,
                                          const rocblas_stride shiftb,
                                          const rocblas_stride strideb)
{
    int bid = blockIdx.x;
    T* alpha = load_ptr_batch<T>(alphaA, bid, shifta, stridea);
    S* beta = betaA + bid * strideb + shiftb;

    if constexpr(rocblas_is_complex<T>)
        beta[0] = alpha[0].real();  // Complex: take real part for beta
    else
        beta[0] = alpha[0];  // Real: direct copy
}
```

**Behavior:**
- tau[batch] = 0 for all batches (identity reflection)
- If beta provided: beta[batch] = alpha[batch] (diagonal unchanged)
- If beta is null: alpha unchanged
- No vector operations (x not accessed)
- Returns success immediately after setup

