    // j=1: row=3, tau_idx=2, vec_len=3, diagonal=A(3,2)
    // j=2: row=2, tau_idx=1, vec_len=2, diagonal=A(2,1)
    // j=3: row=1, tau_idx=0, vec_len=1, diagonal=A(1,0) ← Stop (row 0 unchanged)

