            lda,                                  // Stride: lda (row elements)
            strideA, batch_count);
    }

    // Generate Householder reflector
    rocsolver_larfg_template(
        handle,
        vec_len,                                  // Vector length: n-j
        A, shiftA + idx2D(row, diag_col, lda),   // Alpha: A(m-j-1, n-j-1)
        A, shiftA + idx2D(row, 0, lda),          // x: A(m-j-1, 0:n-j-2)
