    ROCSOLVER_LAUNCH_KERNEL((set_diag<T>),
                            dim3(batch_count, 1, 1), dim3(1, 1, 1), 0, stream,
                            diag, 0, 1,
                            A, shiftA + idx2D(row, diag_col, lda),
                            lda, strideA, 1, true);

