template <typename T, typename I, typename INFO, typename U, std::enable_if_t<rocblas_is_complex<T>, int> = 0>
ROCSOLVER_KERNEL void sqrtDiagOnward(U A,
                                     const rocblas_stride shiftA,
                                     const rocblas_stride strideA,
                                     const size_t loc,
                                     const I j,
                                     T* res,
                                     INFO* info)
{
    I id = hipBlockIdx_x;

    T* M = load_ptr_batch<T>(A, id, shiftA, strideA);
    auto t = M[loc].real() - res[id].real();  // Extract real part!

    if(t <= 0.0)
    {
        if(info[id] == 0)
            info[id] = j + 1;
        M[loc] = t;
        res[id] = 0;
    }
    else
    {
        M[loc] = sqrt(t);  // Result is real
        res[id] = 1 / M[loc];  // Reciprocal is real
    }
}

