    return rocblas_status_invalid_pointer;

// reduce A to tridiagonal form
rocsolver_sytrd_hetrd_template<BATCHED>(handle, uplo, n, A, shiftA, lda, strideA, D, strideD, E,
                                        strideE, tau, n, batch_count, scalars, (T*)work1,
