        // Compute λ*v and residual
        double residual = 0.0;
        for(int i = 0; i < n; i++)
        {
            lv[i] = h_W[0] * h_Z[i];
            double diff = Av[i] - lv[i];
            residual += diff * diff;
        }
        residual = std::sqrt(residual);

        std::cout << "Residual ||A*v - λ*v|| = " << residual << "\n";
        if(residual < 1e-10)
            std::cout << "Eigenvector is accurate!\n";
