template <typename T>
ROCSOLVER_KERNEL void sygv_update_info(T* info, T* iinfo, const rocblas_int n, const rocblas_int bc)
{
    int b = hipBlockIdx_x * hipBlockDim_x + hipThreadIdx_x;

    if(b < bc)
    {
        T infob = info[b];
        T iinfob = iinfo[b];

        if(infob == 0)
            info[b] = iinfob;
        else
            info[b] = infob + n;
    }
}
