answer:
Simplified TRTRI implementation (unblocked):

```cpp
// File: rocsolver_trtri_simple.hpp
#pragma once

#include "rocblas.hpp"

template <typename T>
ROCSOLVER_KERNEL void invdiag_simple(
    const rocblas_diagonal diag,
    const rocblas_int n,
    T* A,
    const rocblas_int lda,
    T* alphas)
{
    int i = hipBlockIdx_x * hipBlockDim_x + hipThreadIdx_x;

    if(i < n)
    {
        if(A[i + i*lda] != 0 && diag == rocblas_diagonal_non_unit)
        {
            A[i + i*lda] = 1.0 / A[i + i*lda];
            alphas[i] = -A[i + i*lda];
        }
        else
            alphas[i] = -1.0;
    }
}

template <typename T>
ROCSOLVER_KERNEL void check_singularity_simple(
    const rocblas_int n,
    T* A,
    const rocblas_int lda,
    rocblas_int* info)
{
    for(int i = 0; i < n; i++)
    {
        if(A[i + i*lda] == 0)
        {
            *info = i + 1;  // 1-based index
            return;
        }
    }
    *info = 0;
}

template <typename T>
rocblas_status rocsolver_trtri_simple(
    rocblas_handle handle,
    const rocblas_fill uplo,
    const rocblas_diagonal diag,
    const rocblas_int n,
    T* A,
    const rocblas_int lda,
    rocblas_int* info)
{
    // 1. Argument validation
    if(!handle)
        return rocblas_status_invalid_handle;

    if(uplo != rocblas_fill_upper && uplo != rocblas_fill_lower)
        return rocblas_status_invalid_value;
    if(diag != rocblas_diagonal_unit && diag != rocblas_diagonal_non_unit)
        return rocblas_status_invalid_value;

    if(n < 0 || lda < n)
        return rocblas_status_invalid_size;

    if((n && !A) || !info)
        return rocblas_status_invalid_pointer;

    if(n == 0) {
        *info = 0;
        return rocblas_status_success;
    }

    hipStream_t stream;
    rocblas_get_stream(handle, &stream);

    // 2. Allocate workspace
    T* work;  // TRMV workspace
    T* alphas;  // Diagonal reciprocals

    hipMalloc(&work, n * sizeof(T));
    hipMalloc(&alphas, n * sizeof(T));

    // 3. Check singularity (non-unit diagonal only)
    if(diag == rocblas_diagonal_non_unit)
    {
        ROCSOLVER_LAUNCH_KERNEL(
            (check_singularity_simple<T>),
            dim3(1), dim3(1), 0, stream,
            n, A, lda, info);

        // Check if singular
        rocblas_int h_info;
        hipMemcpy(&h_info, info, sizeof(rocblas_int),
                  hipMemcpyDeviceToHost);
        if(h_info > 0) {
            hipFree(work);
            hipFree(alphas);
            return rocblas_status_success;  // Singular, abort
        }
    }
    else {
        hipMemset(info, 0, sizeof(rocblas_int));
    }

    // 4. Invert diagonal and compute alphas
    rocblas_int blocks = (n - 1) / 32 + 1;
    ROCSOLVER_LAUNCH_KERNEL(
        (invdiag_simple<T>),
        dim3(blocks), dim3(32), 0, stream,
        diag, n, A, lda, alphas);

    // 5. Set pointer mode for BLAS calls
    rocblas_pointer_mode old_mode;
    rocblas_get_pointer_mode(handle, &old_mode);
    rocblas_set_pointer_mode(handle, rocblas_pointer_mode_device);

    // 6. Unblocked inversion (TRTI2)
    if(uplo == rocblas_fill_upper)
    {
        // Forward sweep: j = 1 to n-1
        for(rocblas_int j = 1; j < n; j++)
        {
            // work = U^(-1)[0:j, 0:j] * U[0:j, j]
            rocblasCall_trmv<T>(
                handle, uplo, rocblas_operation_none, diag,
                j,  // Size of upper-left block
                A, 0, lda, 0,  // Matrix U^(-1)
                A, idx2D(0, j, lda), 1, 0,  // Column j
                work, 0, 1);

            // U^(-1)[0:j, j] = alphas[j] * work
            rocblasCall_scal<T>(
                handle, j,
                alphas + j, 0,  // Scale by -1/U[j,j]
                A, idx2D(0, j, lda), 1, 0, 1);
        }
    }
    else  // rocblas_fill_lower
    {
        // Backward sweep: j = n-2 down to 0
        for(rocblas_int j = n - 2; j >= 0; j--)
        {
            rocblas_int m = n - j - 1;  // Submatrix size

            // work = L^(-1)[j+1:n, j+1:n] * L[j+1:n, j]
            rocblasCall_trmv<T>(
                handle, uplo, rocblas_operation_none, diag,
                m,
                A, idx2D(j+1, j+1, lda), lda, 0,
                A, idx2D(j+1, j, lda), 1, 0,
                work, 0, 1);

            // L^(-1)[j+1:n, j] = alphas[j] * work
            rocblasCall_scal<T>(
                handle, m,
                alphas + j, 0,
                A, idx2D(j+1, j, lda), 1, 0, 1);
        }
    }

    rocblas_set_pointer_mode(handle, old_mode);

    // 7. Cleanup
    hipFree(work);
    hipFree(alphas);

    return rocblas_status_success;
}

// C API wrapper
extern "C" rocblas_status rocsolver_strtri_simple(
    rocblas_handle handle,
    const rocblas_fill uplo,
    const rocblas_diagonal diag,
    const rocblas_int n,
    float* A,
    const rocblas_int lda,
    rocblas_int* info)
{
    return rocsolver_trtri_simple<float>(
        handle, uplo, diag, n, A, lda, info);
}
